head.script:
///////// 1. 변수 및 선언 영역 /////////
scwin.screenId = "ULDSTF05911";
scwin.isurCd = "";          // 발행기관코드
scwin.bzProcsNo = "";       // 업무처리번호 — 비어 있으면 신규, 있으면 수정
scwin.gubun = "";           // 발행사/기초자산 구분 (1 발행사 / 2 기초자산) — 종목 선택 팝업에 넘긴다
scwin.trJob = "";           // 처리구분 I: 저장, U: 수정, D: 삭제
scwin.curDate = "";         // 서버 현재일 (yyyyMMdd)
scwin.KO_KIND_CD = "3";     // ELW 권리형태종류코드 — 이 값인 행만 변경후 조기종료발생기준가격 편집 (§6.3, §10 #8)
// 원본 : /lstproc/ULDSTF05911.gfm (ELW 행사가격/전환비율 변경 팝업)
/*
 * 화면 동작
 *  - 부모(ULDSTF05908 변경상장)가 넘긴 업무처리번호가 없으면 신규, 있으면 수정이다.
 *  - 종목은 종목선택 팝업(ULDSTF92023) 결과나 엑셀 업로드로 그리드를 통째로 바꾼다.
 *  - 종목마다 변경후 행사가격·전환비율(조기종료 ELW 는 조기종료발생기준가격도)을 입력해 등록·수정·삭제한다.
 *  - 통신·데이터 정의는 ULDSTF05911_API.md 명세 기준(register·modify·remove·select-list-isu).
 * 업무 분석 : conversion/gfm-front/ui/ULDSTF05911/ULDSTF05911.md (§번호는 이 문서의 절)
 */

// 부모 화면에서 넘겨받는 값 (§1.2)

// 화면 상태값

// 고정값

// 이 화면의 역할→버튼 매핑 — 상태별 활성 정책은 공통(BTN_STATE_MAP)이 보유한다.
scwin.BTN_MAP = {
    save : "btn_Save",          // [저장]
    modify : "btn_Update",      // [수정]
    "delete" : "btn_Delete"     // [삭제]
};

///////// 2. 초기화 영역 /////////
/**
 * @method
 * @name scwin.onpageload
 * @author Inswave
 * @date 2026. 10. 26
 * @description 페이지로드. 로딩 로직은 scwin.init 하나에 둔다(code-convention 초기화 절). (§3)
 * @returns
 * @hidden N
 */
scwin.onpageload = async function () {
    try {
        await scwin.init();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.onpageload" });
    }
};

/**
 * @method
 * @name scwin.init
 * @author Inswave
 * @date 2026. 10. 26
 * @description 로딩 — 버튼 잠금 → 파라미터 수신 → 신규 준비(scwin.initNewForm) 또는 수정 조회. (원본 gform onload — §3)
 * @returns
 * @hidden N
 */
scwin.init = async function () {
    // 1) 로딩 동안 버튼 잠금 — 조회가 예외로 끝나도 버튼이 XML 기본값(전부 활성)으로 남지 않게 한다.
    $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);

    // 2) 파라미터 수신 — 원본 frame.Provider("../").fn_GetPar(arrPar) (§1.2)
    const param = $c.data.getParameter() ?? {};

    scwin.isurCd = param.isurCd ?? "";          // AS-IS arr[0]
    scwin.bzProcsNo = param.bzProcsNo ?? "";    // AS-IS arr[4]
    scwin.gubun = param.gubun ?? "";            // AS-IS arr[5]

    $c.date.checkCalendarFormat(edt_MktactEnforceDd, "yyyyMMdd");
    scwin.curDate = $c.date.getServerDateTime("yyyyMMdd");

    // 3) 업무처리번호 유무로 신규 준비 또는 수정 조회
    if ($c.util.isEmpty(scwin.bzProcsNo)) {
        scwin.initNewForm();
    } else {
        await scwin.selectList();
    }
};

///////// 3. 컴포넌트 이벤트 영역 /////////
/**
 * @method
 * @name scwin.btn_Save_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 저장 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Save_onclick = async function (e) {
    try {
        await scwin.save();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.btn_Save_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Update_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 수정 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Update_onclick = async function (e) {
    try {
        await scwin.update();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.btn_Update_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_Delete_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 삭제 버튼 클릭
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_Delete_onclick = async function (e) {
    try {
        await scwin.remove();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.btn_Delete_onclick" });
    }
};

/**
 * @method
 * @name scwin.img_SetIsuCd_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 종목 찾기 클릭 — 종목선택 팝업 결과로 그리드를 통째로 바꾼다. (§6.4, §1.4 업무 2)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_SetIsuCd_onclick = async function (e) {
    try {
        await scwin.openIsuPopup();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.img_SetIsuCd_onclick" });
    }
};

/**
 * @method
 * @name scwin.btn_exelUpload_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 엑셀업로드 클릭 — 처리는 scwin.uploadExcel. (원본 SetDataHeader + LoadExcelData — §6.5)
 * 업로드가 끝나면 grd_isu_onfilereadend 에서 조기종료기준가격 편집 조건을 다시 적용한다.
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.btn_exelUpload_onclick = async function (e) {
    try {
        await scwin.uploadExcel();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.btn_exelUpload_onclick" });
    }
};

/**
 * @method
 * @name scwin.grd_isu_onfilereadend
 * @author Inswave
 * @date 2026. 10. 26
 * @description 엑셀 업로드 완료 — 조기종료기준가격 편집 조건을 다시 적용한다.
 * 원본 업로드 머리글에는 권리형태·상장방식 열이 없어 업로드한 행은 편집할 수 없고 상장방식도 비어 있다(§8 #4).
 * @param {Object} e 이벤트 정보
 * @returns
 * @hidden N
 */
scwin.grd_isu_onfilereadend = async function (e) {
    try {
        // TODO: 업로드 행의 elwRghtTpKindCd·listMethdTpCd 보강 방법 결정 (§10 #7)
        scwin.applyKoEditable();
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.grd_isu_onfilereadend" });
    }
};

/**
 * @method
 * @name scwin.img_Excel_onclick
 * @author Inswave
 * @date 2026. 10. 26
 * @description 엑셀저장 클릭 — 그리드를 엑셀로 내려받는다. 0건 안내는 공통 함수가 한다. (원본 GridToExcel, doLogSave 삭제 — §6.6)
 * @param {Object} e 이벤트 객체
 * @returns
 * @hidden N
 */
scwin.img_Excel_onclick = async function (e) {
    try {
        // 파일명에 "/" 를 쓰면 저장이 실패하거나 이름이 잘릴 수 있어 "_" 로 바꾼다(원본 "ELW 행사겨격/전환비율 변경").
        $c.data.downloadGridViewExcel(grd_isu, { fileName : "ELW 행사가격_전환비율 변경" });
    } catch (ex) {
        await $c.exception.handleError(ex, { context : "ULDSTF05911.img_Excel_onclick" });
    }
};

///////// 4. 서브미션 콜백 영역 /////////
/**
 * @method
 * @name scwin.selectList
 * @author Inswave
 * @date 2026. 10. 26
 * @description 수정: 업무처리번호로 종목 목록을 조회하고, 첫 행의 변경상장일·변경사유를 입력란에 보이고, 변경상장일로 버튼 상태를 정한다.
 * (원본 fn_search + dts_Isu OnLoadCompleted — §5.1)
 * @returns
 * @hidden N
 */
scwin.selectList = async function () {
    const sbmOptions = {
        id : "sbm_selectList",
        method : "get",
        action : "/api/listing/lstproc/elw/chg-listing-prc/select-list-isu",
        // TODO: 명세 응답은 dataMap(dma_detail)이나 종목 여러 건 — 목록인지 확인 (§10 #1)
        target : "dlt_detail=body",
        gridview : "grd_isu",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, { bzProcsNo : scwin.bzProcsNo });
    if (result?.skipped) return;    // 진행 중 조회가 있어 이번 호출은 건너뜀

    // 실패하면 버튼을 모두 잠근다 — 첫 로딩은 init 이 걸어 둔 잠금이 남지만, 등록 뒤 재조회 실패면
    // 신규 상태(insert, [저장] 활성)가 남아 같은 건을 다시 등록할 수 있으므로 명시적으로 잠근다.
    if (!result.responseJSON?.success) {
        $c.util.setButtonState("grpBtnBox", "disabled", scwin.BTN_MAP);
        return;
    }

    scwin.applyHeader();
    scwin.applyKoEditable();

    // 변경상장일이 오늘 이후면 update(수정·삭제), 지났으면 error(처리 버튼 없음)
    $c.stf.setButtonSetWithDate(edt_MktactEnforceDd, false, "grpBtnBox", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.saveTrs
 * @author Inswave
 * @date 2026. 10. 26
 * @description 등록(I)·수정(U). 명세 요청 정의(register: dma_register·dlt_register_isuList / modify: dma_update·dlt_update_isuList)에
 * 담아 보낸다 — setJSON 이 정의된 키만 남겨 명세 밖 값은 보내지 않는다. (원본 fn_save_trs + trs — §5.2, §5.3)
 * 전달 방식은 명세가 정한 대로다: 머리 dataMap 은 executeDynamic 의 ref 를 쓰지 않고 requestData 최상위 필드로,
 * 종목 목록 dataList 는 requestData.isuList 로 보낸다(ULDSTF05911_API.md, 2026-10-26 갱신).
 * @param {String} trJob 처리구분 I: 저장, U: 수정
 * @returns
 * @hidden N
 */
scwin.saveTrs = async function (trJob) {
    const isInsert = (trJob === "I");
    const jobNm = isInsert ? "저장" : "수정";
    const reqMst = isInsert ? dma_register : dma_update;
    const reqList = isInsert ? dlt_register_isuList : dlt_update_isuList;

    // TODO: 원본은 LIST_BZ_TP_CD 147·SCREN_ID 등을 보냈으나 명세에 없음 (§10 #9)
    reqMst.setEmptyValue();
    reqMst.setJSON({
        bzProcsNo : isInsert ? "" : scwin.bzProcsNo,     // 명세: 수정 시 필수, 등록 시 서버채번
        isurCd : scwin.getIsurCd(),
        chgDd : dma_mst.get("chgDd"),
        chgRsnContn : dma_mst.get("chgRsnContn")
    });
    // TODO: 수정 시 행 PK(chgListMktactAdmNo·bf/afchgBybzprocsSeq)는 요청 정의에 없음 (§10 #3)
    reqList.setJSON(dlt_detail.getAllJSON());

    const sbmOptions = {
        id : "sbm_saveTrs",
        method : "post",
        action : isInsert ? "/api/listing/lstproc/elw/chg-listing-prc/register" : "/api/listing/lstproc/elw/chg-listing-prc/modify",
        mediatype : "application/json",
        isProcessMsg : false
        // ref 는 쓰지 않는다 — 명세: 요청 정의 데이터를 requestData 로 전달
    };

    // 명세(2026-10-26 갱신): 머리(dma_register/dma_update) 필드는 requestData 최상위, 목록은 isuList 객체명
    const requestData = {
        ...reqMst.getJSON(),
        isuList : reqList.getAllJSON()
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, requestData);
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", jobNm));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", jobNm));

    if (!isInsert) {
        await scwin.selectList();
        return;
    }

    // 등록은 서버가 채번한다. 응답에 번호가 오면 수정 모드로 다시 조회하고, 오지 않으면 팝업을 닫아 부모가 목록을 다시 읽게 한다.
    // TODO: register 응답에 bzProcsNo 를 받을 수 있는지 확인 (§10 #2)
    const newNo = String(result.responseJSON.body?.bzProcsNo ?? "");
    if ($c.util.isEmpty(newNo)) {
        $c.win.closePopup();
        return;
    }
    scwin.bzProcsNo = newNo;
    await scwin.selectList();
};

/**
 * @method
 * @name scwin.deleteTrs
 * @author Inswave
 * @date 2026. 10. 26
 * @description 삭제(논리삭제). 명세 dma_remove 에 담아 보내고, 성공하면 팝업을 닫는다 — 부모는 await 가 끝나면 다시 조회한다. (§5.4)
 * @returns
 * @hidden N
 */
scwin.deleteTrs = async function () {
    dma_remove.setEmptyValue();
    dma_remove.setJSON({ bzProcsNo : scwin.bzProcsNo, isurCd : scwin.getIsurCd() });

    const sbmOptions = {
        id : "sbm_deleteTrs",
        method : "post",
        action : "/api/listing/lstproc/elw/chg-listing-prc/remove",
        mediatype : "application/json",
        isProcessMsg : false
    };

    const result = await $c.sbm.executeDynamic(sbmOptions, dma_remove.getJSON());
    if (result?.skipped) return;    // 진행 중 처리가 있어 이번 호출은 건너뜀

    if (!result.responseJSON?.success) {
        await $c.win.alert($c.stf.getMessageParam("MSG-A002", "삭제"));
        return;
    }

    await $c.win.alert($c.stf.getMessageParam("MSG-A001", "삭제"));
    $c.win.closePopup();
};

///////// 5. 일반/업무 함수 영역 /////////
/**
 * @method
 * @name scwin.initNewForm
 * @author Inswave
 * @date 2026. 10. 26
 * @description 신규 준비. 입력과 종목 목록을 비우고 [저장]만 켠다. (원본 fn_new_onload + dts_Isu OnLoadCompleted — §3)
 * @returns
 * @hidden N
 */
scwin.initNewForm = function () {
    dma_mst.setEmptyValue();
    dma_mst.set("isurCd", scwin.isurCd);
    dlt_detail.removeAll();

    $c.util.setButtonState("grpBtnBox", "insert", scwin.BTN_MAP);
};

/**
 * @method
 * @name scwin.validate
 * @author Inswave
 * @date 2026. 10. 26
 * @description 저장·수정 전 입력 검증. 원본 fn_CheckForm 순서를 따른다. (§6.1)
 *  1) 변경상장일 필수·날짜, 익일 이후  2) 변경사유 필수·2000 byte  3) 종목 1건 이상  4) 종목마다 변경후 행사가격·전환비율 입력(0 불가)
 * @returns {Promise<Boolean>} 검증 통과 여부
 * @hidden N
 */
scwin.validate = async function () {
    const dateOptions = {
        validateType : "alert",     // alert|mark|all
        checkType : "single",       // single|multi
        fields : {
            edt_MktactEnforceDd : { required : true, format : "date", name : "변경상장일" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_3, dateOptions)) return false;

    // 변경상장일은 익일 이후 (원본 checkDdTm("DD", …, "변경상장", false) — pcc 함수는 Gauce 속성 .text 를 읽어 쓰지 않는다)
    if (dma_mst.get("chgDd") <= scwin.curDate) {
        await $c.win.alert("[변경상장일]을 익일 이후로 입력하세요.");
        edt_MktactEnforceDd.focus();
        return false;
    }

    const rsnOptions = {
        validateType : "alert",
        checkType : "single",
        fields : {
            txb_ChgRsnContn : { required : true, maxLengthB : 2000, name : "변경사유" }
        }
    };
    if (!await $c.validate.validateDataCollect(panel_3, rsnOptions)) return false;

    const rowCount = dlt_detail.getRowCount();
    if (rowCount === 0) {
        await $c.win.alert("[종목]을 선택하세요.");
        return false;
    }

    for (let i = 0; i < rowCount; i++) {
        const badCol = scwin.isEmptyOrZero(dlt_detail.getCellData(i, "afchgExerPrc")) ? "afchgExerPrc"
            : scwin.isEmptyOrZero(dlt_detail.getCellData(i, "afchgConvRto")) ? "afchgConvRto" : "";
        if (badCol !== "") {
            await $c.win.alert($c.stf.getMessageParam("MSG-0019", ""));
            grd_isu.setFocusedCell(i, badCol);     // 원본에는 없는 포커스 이동 — 비어 있는 열로 (§6.1)
            return false;
        }
    }

    // TODO: 조기종료 ELW 의 변경후 조기종료발생기준가격은 원본도 검증하지 않음 (§8 #3, §10 #8)
    return true;
};

/**
 * @method
 * @name scwin.isEmptyOrZero
 * @author Inswave
 * @date 2026. 10. 26
 * @description 값이 비었거나 0 인지. 원본의 느슨한 비교(== "" || == 0)를 숫자 비교로 옮긴다(§8 #2).
 * @param {*} value 셀 값
 * @returns {Boolean} 비었거나 0 이면 true
 * @hidden N
 */
scwin.isEmptyOrZero = function (value) {
    return $c.util.isEmpty(value) || Number(value) === 0;
};

/**
 * @method
 * @name scwin.applyHeader
 * @author Inswave
 * @date 2026. 10. 26
 * @description 수정 조회 뒤 첫 행의 변경상장일·변경사유를 입력란(dma_mst)에 보인다. 행마다 다르면 첫 행이 이긴다(원본과 같음, §8 #13).
 * @returns
 * @hidden N
 */
scwin.applyHeader = function () {
    if (dlt_detail.getRowCount() === 0) {
        dma_mst.set("isurCd", scwin.isurCd);
        return;
    }
    dma_mst.set("isurCd", dlt_detail.getCellData(0, "isurCd") || scwin.isurCd);
    dma_mst.set("chgDd", dlt_detail.getCellData(0, "chgDd"));
    dma_mst.set("chgRsnContn", dlt_detail.getCellData(0, "chgRsnContn"));
};

/**
 * @method
 * @name scwin.applyKoEditable
 * @author Inswave
 * @date 2026. 10. 26
 * @description 권리형태종류코드가 KO_KIND_CD 인 행만 변경후 조기종료발생기준가격을 편집할 수 있게 한다.
 * (원본 그리드 edit="{IF(ELW_RGHT_TP_KIND_CD='3', 'true','false')}" — §6.3)
 * @returns
 * @hidden N
 */
scwin.applyKoEditable = function () {
    const rowCount = dlt_detail.getRowCount();
    for (let i = 0; i < rowCount; i++) {
        // 서버·종목선택 팝업이 숫자 3 으로 줄 수도 있어 문자열로 맞춰 비교한다
        const isKo = (String(dlt_detail.getCellData(i, "elwRghtTpKindCd") ?? "") === scwin.KO_KIND_CD);
        grd_isu.setCellReadOnly(i, "afchgElwKoOccrBasPrc", !isKo);
    }
};

/**
 * @method
 * @name scwin.getIsurCd
 * @author Inswave
 * @date 2026. 10. 26
 * @description 전문에 넣을 발행기관코드. 수정은 조회 값, 신규는 부모가 넘긴 값이다.
 * @returns {String} 발행기관코드
 * @hidden N
 */
scwin.getIsurCd = function () {
    return dma_mst.get("isurCd") || scwin.isurCd;
};

/**
 * @method
 * @name scwin.openIsuPopup
 * @author Inswave
 * @date 2026. 10. 26
 * @description 종목선택 팝업(ULDSTF92023)을 현재 그리드와 함께 열고, 고른 결과로 그리드를 바꾼다.
 * (원본 fn_GetParIsu/fn_SetParIsu 바꿔 끼우기 + fn_PopFindElwCode — §6.4, 가이드 §6.5)
 * pcc $c.lc.popFindElwCode 는 값을 넘기지 않는 콜백형이라 쓰지 않는다.
 * @returns
 * @hidden N
 */
scwin.openIsuPopup = async function () {
    const data = {
        isurCd : scwin.getIsurCd(),         // AS-IS arrPar[0]
        gubun : scwin.gubun,                // AS-IS arrPar[1] — 1 발행사 / 2 기초자산
        isuList : dlt_detail.getAllJSON()   // AS-IS CopyDataSet(dts_Isu, param_dts)
    };
    const options = {
        id : "ULDSTF92023",
        popupName : "종목선택",
        width : 510,
        height : 430,
        type : "pageFramePopup"
    };

    // TODO: 92023 전환본이 없어 경로·반환 키(list)·행 컬럼은 가정 (§10 #5)
    const result = await $c.win.openPopup("/ui/listingcommon/ULDSTF92023.xml", options, data);

    // 취소·닫기(X)도 { isCloseButtonClick } 객체가 온다 → 목록 필드로 판정한다.
    if (!Array.isArray(result?.list)) return;

    // AS-IS fn_SetParIsu: 선택 결과로 그리드 전체를 바꾼다.
    dlt_detail.setJSON(result.list);
    scwin.applyKoEditable();
};

/**
 * @method
 * @name scwin.save
 * @author Inswave
 * @date 2026. 10. 26
 * @description 등록. 검증 → 확인 → 등록 순서 (원본 fn_save — §6.7). 명세상 서버 채번이라 화면 채번은 하지 않는다(§10 #2).
 * @returns
 * @hidden N
 */
scwin.save = async function () {
    scwin.trJob = "I";

    if (!await scwin.validate()) return;

    // "[저장] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.update
 * @author Inswave
 * @date 2026. 10. 26
 * @description 수정. 검증 → 확인 → 수정 순서. 원본처럼 바뀐 내용이 없어도 보낸다(§8 #10). (원본 fn_update — §6.8)
 * @returns
 * @hidden N
 */
scwin.update = async function () {
    scwin.trJob = "U";

    if (!await scwin.validate()) return;

    // "[수정] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.saveTrs(scwin.trJob);
};

/**
 * @method
 * @name scwin.remove
 * @author Inswave
 * @date 2026. 10. 26
 * @description 삭제. 확인을 받은 뒤 삭제한다. 입력 검증은 하지 않는다. (원본 fn_delete — §6.9)
 * @returns
 * @hidden N
 */
scwin.remove = async function () {
    scwin.trJob = "D";

    // "[삭제] 처리를 하시겠습니까?" — 업무공통 MSG-A006
    if (!await $c.lc.isProcess(scwin.trJob)) return;

    await scwin.deleteTrs();
};

/**
 * @method
 * @name scwin.uploadExcel
 * @author Inswave
 * @date 2026. 10. 26
 * @description 확인을 받은 뒤 엑셀 자료로 그리드 전체를 바꾼다. 업로드가 끝나면 grd_isu_onfilereadend 가 편집 조건을 다시 적용한다. (§6.5)
 * @returns
 * @hidden N
 */
scwin.uploadExcel = async function () {
    if (!await $c.win.confirm("엑셀자료를 업로드 하시면 그리드의 내용이 엑셀 데이터로 변경됩니다.")) return;

    // 원본 LoadExcelData('', 'Sheet1', 2, 0, 2) — 첫 시트, 1행 머리글 다음 2행부터, 그리드 전체 교체.
    // decimal 8 : 행사가격 소수 8자리(전환비율 6·조기종료가격 3 포함)가 기본 4자리로 반올림되지 않게 한다.
    // TODO: 원본 형식(머리글 1행)과 TO-BE 다운로드 형식(머리글 2행) 파일로 시작 행 실측 (§10 #7)
    $c.data.uploadGridViewExcel(grd_isu, {
        sheetNo : 0,
        startRowIndex : 0,
        headerExist : "1",
        append : "0",
        decimal : "8"
    });
};
